Definition:
=if(
not(iferror(regexmatch(jcts_l_pipe_separated_string,"|"),FALSE)),input_jct_r,
let(
jcts_l,split(jcts_l_pipe_separated_string,"|"),
jcts_r,split(jcts_r_pipe_separated_string,"|"),
if(counta(jcts_l)<>counta(jcts_r),#VALUE!,
if(regexmatch(jcts_l,"\_"),
if(or(
   regexmatch(jcts_l_pipe_separated_string,"^"&input_jct_r&"[\_|]"),
   regexmatch(jcts_l_pipe_separated_string,"[\_|]"&input_jct_r&"[\_|]"),
   regexmatch(jcts_l_pipe_separated_string,"[\_|]"&input_jct_r&"$")),
 let(match_array,map(jcts_l,lambda(x,not(or(regexmatch(x,"^"&input_jct_r&"\_"),regexmatch(x,"\_"&input_jct_r&"$"),x=input_jct_r)))),
 iferror(
  MATCH_FRAGMENT_JUNCTIONS_3PRIME(
  join("|",filter(jcts_l,match_array)),
  join("|",filter(jcts_r,match_array)),
 let(rm,index(jcts_r,xmatch(FALSE,match_array)),
  if(regexmatch(rm,"\_"),
   if(regexmatch(index(jcts_l,xmatch(FALSE,match_array)),"\_"&input_jct_r&"$"),index(split(rm,"_"),2),index(split(rm,"_"),1)),
   rm))),
 FALSE)),
let(match_array,map(jcts_r,lambda(x,not(or(regexmatch(x,"^"&input_jct_r&"\_"),regexmatch(x,"\_"&input_jct_r&"$"),x=input_jct_r)))),
 iferror(
  MATCH_FRAGMENT_JUNCTIONS_3PRIME(
  join("|",filter(jcts_l,match_array)),
  join("|",filter(jcts_r,match_array)),
 let(rm,index(jcts_l,xmatch(FALSE,match_array)),
  if(regexmatch(rm,"\_"),
   if(regexmatch(index(jcts_l,xmatch(FALSE,match_array)),"\_"&input_jct_r&"$"),index(split(rm,"_"),2),index(split(rm,"_"),1)),
   rm))),
 FALSE)))
,
if(isnumber(xmatch(input_jct_r,jcts_l)),
 let(match_array,map(jcts_l,lambda(x,x<>input_jct_r)),
 iferror(
  MATCH_FRAGMENT_JUNCTIONS_3PRIME(
  join("|",filter(jcts_l,match_array)),
  join("|",filter(jcts_r,match_array)),
  index(jcts_r,xmatch(FALSE,match_array))),
 FALSE)),
 let(match_array,map(jcts_r,lambda(x,x<>input_jct_r)),
 iferror(
  MATCH_FRAGMENT_JUNCTIONS_3PRIME(
  join("|",filter(jcts_l,match_array)),
  join("|",filter(jcts_r,match_array)),
  index(jcts_l,xmatch(FALSE,match_array))),
 FALSE))
)))))
